(function(){
'use strict';
const $=id=>document.getElementById(id),D=BioCasaData,B=BioCasa,form=$('teacher-config'),button=$('download-package');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);
let dataset=D.validate(D.current,B.ACCOUNTS,B.PRODUCTS),candidate=null;
function totals(d){const sum=type=>B.ACCOUNTS.filter(a=>type.includes(a.type)).reduce((n,a)=>n+(d.openingBalances[a.id]||0),0);return {assets:sum(['asset']),debts:sum(['liability']),equity:sum(['equity'])};}
function datasetHTML(d){const t=totals(d);return `<div class="dataset-summary"><div><span>Schuljahr · Klasse ${d.grade}</span><strong>${esc(d.schoolYear)}</strong></div><div><span>Vermögen</span><strong>${euro(t.assets)}</strong></div><div><span>Schulden</span><strong>${euro(t.debts)}</strong></div><div><span>Eigenkapital</span><strong>${euro(t.equity)}</strong></div></div><p><strong>${esc(d.label)}</strong><br><small>${esc(d.source.title)} · ${esc(d.source.reference)}</small></p><p class="help-text">Fallzeitraum 01.10.–31.12.${d.caseYear} · ${d.demoEntries.length} Demobelege · ${d.receipts.length} auswählbare Übungsbelege. Die zusätzlichen Übungsbelege sind noch nicht gebucht.</p><details class="dataset-details"><summary>Anfangsbestände, Herkunft und ergänzende Annahmen prüfen</summary><div class="table-wrap"><table><thead><tr><th>Konto</th><th class="num">Anfangsbestand</th></tr></thead><tbody>${Object.entries(d.openingBalances).map(([id,value])=>`<tr><td>${esc(id+' · '+B.byId[id].name)}</td><td class="num">${euro(value)}</td></tr>`).join('')}</tbody></table></div>${d.assumptions.map(a=>`<div class="dataset-assumption ${a.origin==='practice'?'practice':''}"><strong>${a.origin==='md'?'MD-Bezug':'OS-Ergänzung'} · ${esc(a.title)}</strong><p>${esc(a.basis)}</p></div>`).join('')}<p class="help-text">Die Herkunftstexte beziehen sich auf die Ausgangsdatei. Bei eigenen Änderungen Angaben und Herleitung ebenfalls aktualisieren.</p></details><details class="dataset-details"><summary>Lehrbuchverweise für diesen Jahrgang</summary><p>${esc(d.source.bookEdition)}<br><small>${esc(d.source.bookSource)}</small></p>${Object.entries(d.bookReferences).map(([id,refs])=>`<p><strong>${esc({inventory:'Inventur',inventar:'Inventar',balance:'Bilanz',accounts:'Bestandskonten',income:'Erfolgskonten',tax:'Vor-/Umsatzsteuer',further:'Weitere Buchungen',returns:'Retouren',accrual:'Abgrenzung',stock:'Lager',control:'Controlling'}[id])}</strong>: ${refs.length?refs.map(r=>esc(r.topic)+' · S. '+esc(r.pages)).join('; '):'Keine gesonderte Seitenfundstelle in der MD.'}</p>`).join('')}</details>`;}
function feedback(message,error=false){$('dataset-feedback').className=error?'alert warn':'help-text';$('dataset-feedback').textContent=message;}
function renderDataset(){ $('dataset-year').value=dataset.caseYear;$('dataset-preview').innerHTML=datasetHTML(dataset); }
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('dataset-template').addEventListener('click',()=>download('BioCasa_Datenbasis_Jg11_'+dataset.schoolYear.replace('/','-')+'.json',JSON.stringify(dataset,null,2),'application/json'));
$('dataset-default').addEventListener('click',()=>{dataset=D.validate(D.defaultConfig,B.ACCOUNTS,B.PRODUCTS);candidate=null;$('dataset-candidate').hidden=true;renderDataset();feedback('Die MD-Ausgangsdaten für 2026/27 sind ausgewählt. Persönliche Übungsstände wurden nicht verändert.');});
$('dataset-year').addEventListener('change',()=>{try{dataset=D.validate(D.shiftYear(dataset,$('dataset-year').value),B.ACCOUNTS,B.PRODUCTS);candidate=null;$('dataset-candidate').hidden=true;renderDataset();feedback('Falljahr und Belegdaten angepasst. Werte und Herkunft bleiben nachvollziehbar.');}catch(e){$('dataset-year').value=dataset.caseYear;feedback(e.message,true);}});
$('dataset-upload').addEventListener('change',async event=>{
 const file=event.target.files?.[0];if(!file)return;candidate=null;$('dataset-candidate').hidden=true;
 try{if(file.size>100000||!file.name.toLowerCase().endsWith('.json'))throw Error('Wähle eine BioCasa-JSON-Vorlage mit höchstens 100 KB.');candidate=D.validate(JSON.parse(await file.text()),B.ACCOUNTS,B.PRODUCTS);$('dataset-candidate').hidden=false;$('dataset-candidate').innerHTML='<h3>Upload geprüft · Vorschau vor der Auswahl</h3>'+datasetHTML(candidate)+'<button class="btn primary" type="button" id="dataset-accept">Diese Datenbasis für das Paket auswählen</button> <button class="btn tiny" type="button" id="dataset-cancel">Bisherige Auswahl behalten</button>';$('dataset-accept').addEventListener('click',()=>{dataset=candidate;candidate=null;$('dataset-candidate').hidden=true;renderDataset();feedback('Upload ausgewählt. Er wird mit dem neu erstellten Moodle-Paket übernommen.');});$('dataset-cancel').addEventListener('click',()=>{candidate=null;$('dataset-candidate').hidden=true;feedback('Die bisherige Datenbasis bleibt ausgewählt.');});feedback('Der Upload ist stimmig. Vergleiche Schuljahr, Anfangsbestände und Herkunft in der Vorschau.');}catch(e){feedback('Upload nicht übernommen: '+e.message,true);}finally{event.target.value='';}
});
$('dataset-open-preview').addEventListener('click',()=>{try{window.localStorage.setItem('biocasa-os:teacher-dataset',JSON.stringify(dataset));window.location.href='preview.html';}catch{feedback('Die Vorschau konnte den Datensatz nicht zwischenspeichern. Du kannst das konfigurierte Moodle-Paket weiterhin erstellen.',true);}});
function read(){const mode=form.elements.namedItem('mode').value;return BioCasaRelease.validate({version:1,inventar:{mode,opensAt:mode==='date'?BioCasaRelease.berlinInputToISO($('release-date').value):null}});}
function summary(){const mode=form.elements.namedItem('mode').value;$('release-date').disabled=mode!=='date';try{const c=read().inventar;$('teacher-summary').textContent=c.mode==='automatic'?'Freigabe: automatisch, sobald 5/5 Inventuraufgaben richtig gelöst sind.':c.mode==='hold'?'Freigabe: Inventar bleibt bis zum Ersetzen des Pakets gesperrt.':'Freigabe ab '+new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',dateStyle:'medium',timeStyle:'short'}).format(new Date(c.opensAt))+' Uhr; zusätzlich sind 5/5 gelöste Aufgaben nötig.';}catch(e){$('teacher-summary').textContent=e.message;}}
form.addEventListener('change',summary);form.addEventListener('input',summary);
form.addEventListener('submit',async event=>{
 event.preventDefault();button.disabled=true;$('teacher-feedback').textContent='Paket wird vorbereitet …';
 try{if(candidate)throw Error('Wähle die geprüften Upload-Daten zuerst ausdrücklich aus oder verwende die bisherige Datenbasis.');dataset=D.validate(dataset,B.ACCOUNTS,B.PRODUCTS);const config=read(),response=await fetch('imsmanifest.xml',{cache:'no-store'});if(!response.ok)throw Error('Paketübersicht konnte nicht geladen werden.');const text=await response.text(),xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw Error('Ungültige Paketübersicht.');const names=['imsmanifest.xml',...Array.from(xml.getElementsByTagName('file'),x=>x.getAttribute('href'))];if(!names.includes('data-config.js')||!names.includes('course-config.js'))throw Error('Eine Konfigurationsdatei fehlt.');const files=[];
  for(const name of names){if(!/^[A-Za-z0-9_.\/-]+$/.test(name)||name.split('/').includes('..')||name.startsWith('/'))throw Error('Ungültiger Paketpfad.');if(name==='course-config.js'){files.push({name,data:BioCasaRelease.source(config)});continue;}if(name==='data-config.js'){files.push({name,data:D.source(dataset)});continue;}if(name==='imsmanifest.xml'){files.push({name,data:text});continue;}const part=await fetch(name,{cache:'no-store'});if(!part.ok)throw Error('Paketdatei nicht erreichbar: '+name);files.push({name,data:await part.arrayBuffer()});}
  download('BioCasa_OS_Moodle_SCORM12.zip',BioCasaPackage.zip(files),'application/zip');$('teacher-feedback').textContent='Paket für '+dataset.schoolYear+' erstellt. Neues Schuljahr oder geänderte Buchungsdaten: eigene Moodle-Aktivität oder neuen Versuch verwenden. Unveränderte Datenbasis: bestehende Aktivität wie bisher aktualisieren.';
 }catch(e){$('teacher-feedback').textContent='Paket konnte nicht erstellt werden: '+e.message;}finally{button.disabled=false;}
});
const existing=BioCasaRelease.status(),radio=form.querySelector('input[value="'+existing.mode+'"]');if(radio)radio.checked=true;if(existing.opensAt){const f=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});$('release-date').value=f.format(new Date(existing.opensAt)).replace(' ','T');}summary();renderDataset();
})();
